import{_ as a,C as s,o as i,c as o,ag as r,E as n}from"./chunks/framework.CtWPcAmt.js";const f=JSON.parse('{"title":"Fulfilment Carriers","description":"","frontmatter":{},"headers":[],"relativePath":"orders/fulfilment-carriers.md","filePath":"orders/fulfilment-carriers.md","lastUpdated":1786121967000}'),l={name:"orders/fulfilment-carriers.md"};function c(h,e,d,p,u,m){const t=s("ImagePopup");return i(),o("div",null,[e[0]||(e[0]=r('<h1 id="fulfilment-carriers" tabindex="-1">Fulfilment Carriers <a class="header-anchor" href="#fulfilment-carriers" aria-label="Permalink to &quot;Fulfilment Carriers&quot;">​</a></h1><p>Fulfilment Carriers let the marketplace run shipping <strong>after</strong> an order is placed — sellers buy shipping labels, schedule courier pickups, and report tracking, all through couriers the <strong>admin</strong> connects once for the whole marketplace. Sellers never see the courier credentials.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How fulfilment carriers differ from checkout shipping methods</li><li>How the admin sets up carriers, and the built-in Self Ship option</li><li>What a seller sees at shipment time, by carrier type</li></ul></div><div class="tip custom-block"><p class="custom-block-title">Not a checkout shipping method</p><p>A <strong>checkout shipping method</strong> quotes a delivery rate to the customer <em>before</em> they pay. A <strong>fulfilment carrier</strong> is used <em>after</em> the order, by the seller, to actually ship it. Connecting a carrier never adds an option to customer checkout.</p></div><h2 id="setting-up-carriers-admin" tabindex="-1">Setting up carriers (admin) <a class="header-anchor" href="#setting-up-carriers-admin" aria-label="Permalink to &quot;Setting up carriers (admin)&quot;">​</a></h2><p>Go to <strong>Configure → Marketplace → Fulfilment Carriers</strong>.</p>',6)),n(t,{src:"/images/fulfilment-carriers/admin-config.png",alt:"Fulfilment Carriers configuration"}),e[1]||(e[1]=r('<p>Out of the box, one carrier is always present:</p><ul><li><strong>Self Ship (Manual)</strong> — the built-in fallback: the seller arranges their own courier and types the carrier name and tracking number by hand. It&#39;s always available and cannot be switched off. You can set the <strong>Title Shown To Sellers</strong> that overrides its name in the seller&#39;s shipment form.</li></ul><p>Real couriers (Shiprocket, Delhivery, UPS, FedEx, and so on) arrive as <strong>separate integration packages</strong>. Installing one adds its own section here, where the admin enters that courier&#39;s account credentials once — sellers then ship through it without ever seeing those details. A carrier is only offered to sellers once it&#39;s installed, switched on, and fully configured.</p><h2 id="what-a-carrier-can-do" tabindex="-1">What a carrier can do <a class="header-anchor" href="#what-a-carrier-can-do" aria-label="Permalink to &quot;What a carrier can do&quot;">​</a></h2><p>Carriers declare which capabilities they support, and the seller&#39;s shipment form adapts to match:</p><ul><li><strong>Labels</strong> — generate and buy a shipping label; tracking is filled in automatically and the label is downloadable.</li><li><strong>Pickups</strong> — book a courier collection, either from published <strong>time slots</strong> or within a <strong>ready/close window</strong>.</li><li><strong>Tracking</strong> — status flows back from the carrier automatically.</li></ul><h2 id="what-the-seller-sees-at-shipment-time" tabindex="-1">What the seller sees at shipment time <a class="header-anchor" href="#what-the-seller-sees-at-shipment-time" aria-label="Permalink to &quot;What the seller sees at shipment time&quot;">​</a></h2><p>When a seller ships an order (from <strong>Sales → Orders → the order → Schedule Pickup</strong>), they pick one of the configured carriers:</p><ul><li><strong>Self Ship (Manual)</strong> — the seller enters the courier name and tracking number themselves; nothing is booked.</li><li><strong>Label-capable carrier</strong> — a <strong>Parcel</strong> section (weight and dimensions) appears; the label is bought on submit and its cost and a <strong>Download</strong> button show on the shipment.</li><li><strong>Pickup-capable carrier</strong> — a <strong>Collection</strong> section appears to schedule the courier visit (slot or window) with a pickup date and instructions.</li></ul><p>If a booking fails, the shipment is still saved and marked <strong>Not Booked</strong> so the seller can retry — no shipment is lost.</p><div class="info custom-block"><p class="custom-block-title">For developers</p><p>A courier integration is a standalone package built on the marketplace&#39;s carrier interfaces — see the <a href="https://devdocs.bagisto.com/" target="_blank" rel="noreferrer">Bagisto developer documentation</a> to build one. No marketplace code changes are needed to add a carrier.</p></div>',11))])}const b=a(l,[["render",c]]);export{f as __pageData,b as default};
